def count_ways_to_split_tree(n, parents, colors):
    from collections import defaultdict, deque

    # Build the tree as an adjacency list
    tree = defaultdict(list)
    for i in range(1, n):
        tree[parents[i]].append(i)

    # Count the number of black vertices in each subtree
    def dfs_count_black(node):
        count = colors[node]
        for child in tree[node]:
            count += dfs_count_black(child)
        return count

    # Calculate the number of ways to split the tree
    def dfs_count_ways(node):
        if colors[node] == 1:
            return 1

        total_ways = 1
        for child in tree[node]:
            child_ways = dfs_count_ways(child)
            total_ways = (total_ways * child_ways) % MOD

        return total_ways

    # Check if the tree can be split such that each part has exactly one black vertex
    def can_split():
        black_count = sum(colors)
        if black_count != n - 1:
            return False

        # Perform BFS to check if there is exactly one path from any black vertex to another
        visited = [False] * n
        queue = deque()

        for i in range(n):
            if colors[i] == 1:
                if visited[i]:
                    return False
                queue.append(i)
                visited[i] = True

        while queue:
            node = queue.popleft()
            for child in tree[node]:
                if not visited[child]:
                    visited[child] = True
                    queue.append(child)

        return all(visited)

    if not can_split():
        return 0

    return dfs_count_ways(0)

